tool_calls:
cat << 'EOF' > /home/eval/pkgs/bin/order
#!/usr/bin/env bash
set -e

# Make sure locale is C for byte order comparisons
export LC_ALL=C

if [ $# -ne 1 ]; then
    echo "Usage: $0 <deps-file>" >&2
    exit 2
fi

input_file="$1"

awk '
BEGIN {
    # Initialize
}
{
    # Strip comments (# to end of line)
    sub(/#.*$/, "")
    # Check if line is empty or only whitespace
    if ($0 ~ /^[[:space:]]*$/) next

    # Find the colon
    colon_idx = index($0, ":")
    if (colon_idx == 0) next # or handle error? Standard says each non-comment line has form package: deps

    pkg_str = substr($0, 1, colon_idx - 1)
    deps_str = substr($0, colon_idx + 1)

    # Trim pkg_str
    gsub(/^[[:space:]]+|[[:space:]]+$/, "", pkg_str)
    if (pkg_str == "") next

    all_pkgs[pkg_str] = 1

    # Split deps_str by whitespace
    n_deps = split(deps_str, deps_arr)
    for (i = 1; i <= n_deps; i++) {
        dep = deps_arr[i]
        all_pkgs[dep] = 1
        # Avoid duplicate edges or self-loops if handled properly
        if (!(pkg_str in graph && dep in graph[pkg_str])) {
            # In awk, graph[pkg_str, dep] = 1
            if (!dep_graph[pkg_str, dep]) {
                dep_graph[pkg_str, dep] = 1
                dep_list[pkg_str] = (pkg_str in dep_list ? dep_list[pkg_str] " " dep : dep)
                # dep_count counts how many unique dependencies pkg_str has
                dep_count[pkg_str]++
            }
        }
    }
}
END {
    # Ensure all packages have dep_count entry
    for (p in all_pkgs) {
        if (!(p in dep_count)) {
            dep_count[p] = 0
        }
    }

    # Kahn algorithm with deterministic smallest package selection
    # Emit packages one by one
    total_pkgs = 0
    for (p in all_pkgs) {
        total_pkgs++
    }

    emitted_count = 0

    while (1) {
        # Find candidate: smallest package (byte order) not yet emitted with dep_count == 0
        best_pkg = ""
        for (p in all_pkgs) {
            if (!emitted[p] && dep_count[p] == 0) {
                if (best_pkg == "" || p < best_pkg) {
                    best_pkg = p
                }
            }
        }

        if (best_pkg == "") {
            break
        }

        # Emit best_pkg
        print best_pkg
        emitted[best_pkg] = 1
        emitted_count++

        # For every other package that depends on best_pkg, reduce its dep_count
        for (p in all_pkgs) {
            if (!emitted[p] && dep_graph[p, best_pkg]) {
                dep_count[p]--
            }
        }
    }

    if (emitted_count < total_pkgs) {
        # Remaining packages sorted
        # Collect remaining packages
        n_rem = 0
        for (p in all_pkgs) {
            if (!emitted[p]) {
                n_rem++
                rem_pkgs[n_rem] = p
            }
        }

        # Sort rem_pkgs using simple sort (n_rem is small, or use quicksort / insertion sort)
        for (i = 1; i <= n_rem; i++) {
            for (j = i + 1; j <= n_rem; j++) {
                if (rem_pkgs[j] < rem_pkgs[i]) {
                    tmp = rem_pkgs[i]
                    rem_pkgs[i] = rem_pkgs[j]
                    rem_pkgs[j] = tmp
                }
            }
        }

        cycle_msg = "cycle:"
        for (i = 1; i <= n_rem; i++) {
            cycle_msg = cycle_msg " " rem_pkgs[i]
        }
        print cycle_msg > "/dev/stderr"
        exit 1
    }
}
' "$input_file"
EOF
chmod +x /home/eval/pkgs/bin/order

